```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

/// Render the digest's kept entries as the notification body.
fn render(composed: &Digest) -> String {
    let mut out = format!("Digest {}\n{}\n", composed.date, composed.overview);
    for entry in composed.entries.iter().filter(|e| e.kept) {
        out.push_str(&format!("- {} ({}) {}\n", entry.title, entry.feed, entry.link));
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = crate::aap::caps::notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
